<?php require_once __DIR__.'/lib.php';
// Restore a valid remember-me session before deciding which page to render.
if (empty($_SESSION['user_id']) && !empty($_COOKIE['studio_remember'])) {
  [$uid, $token] = array_pad(explode(':', $_COOKIE['studio_remember'], 2), 2, '');
  $s = db()->prepare('SELECT employee_id FROM users WHERE id=? AND remember_token=? AND active=1');
  $s->execute([(int)$uid, $token]);
  if ($employeeId = $s->fetchColumn()) {
    $_SESSION['user_id'] = $employeeId;
  } else {
    setcookie('studio_remember', '', time() - 3600, '/');
  }
}
$page=$_GET['page']??(me()?'dashboard':'login'); $current=$page;
if ($page === 'login' && $_SERVER['REQUEST_METHOD'] === 'GET') {
  // Kept before authenticated page rendering so a stale session cannot loop
  // through require_login while the sign-in page is being requested.
  if (me()) { header('Location: index.php?page=dashboard'); exit; }
  $f = pull_flash();
  ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/app.css"><title>Sign in · FrameForge</title></head><body class="login"><form class="login-box" method="post"><div class="login-brand">FRAME<span>FORGE</span><div class="sub">Employee Portal</div></div><h1>Welcome Back</h1><p class="muted">Sign in to access your studio portal.</p><?php if($f):?><div class="alert error"><?=esc($f[0])?></div><?php endif?><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Email or Employee ID</label><input name="identity" required autofocus placeholder="admin@frameforge.local"><label style="margin-top:14px">Password</label><div style="display:flex;gap:6px"><input id="password" type="password" name="password" required><button type="button" class="secondary" data-toggle-password="#password">Show</button></div><label style="margin-top:14px"><input type="checkbox" name="remember" style="width:auto"> Remember me</label><button style="width:100%;margin-top:16px" name="action" value="login">Sign in</button><p class="muted" style="font-size:12px">For access recovery, contact your studio administrator.</p></form><script src="assets/app.js"></script></body></html><?php
  exit;
}
function rows($sql,$args=[]){$s=db()->prepare($sql);$s->execute($args);return $s->fetchAll();} function one($sql,$args=[]){$s=db()->prepare($sql);$s->execute($args);return $s->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){
 try { verify_csrf(); $action=$_POST['action']??'';
  if($action==='login'){ $id=trim($_POST['identity']??''); $s=db()->prepare('SELECT u.*,e.id employee_id FROM users u JOIN employees e ON e.id=u.employee_id WHERE (u.email=? OR e.employee_code=?) AND u.active=1 AND e.employment_status="Active"');$s->execute([$id,$id]);$u=$s->fetch(); if(!$u||!password_verify($_POST['password']??'',$u['password_hash'])) throw new RuntimeException('Invalid email/employee ID or password.'); $_SESSION['user_id']=$u['employee_id']; if(!empty($_POST['remember'])){ $t=bin2hex(random_bytes(32));db()->prepare('UPDATE users SET remember_token=? WHERE id=?')->execute([$t,$u['id']]);setcookie('studio_remember',$u['id'].':'.$t,time()+2592000,'','',false,true); } log_action('Signed in'); header('Location: index.php?page=dashboard');exit; }
  if($action==='logout'){session_unset();session_destroy();setcookie('studio_remember','',time()-3600);header('Location:index.php?page=login');exit;}
  if($action==='attendance'){ $u=require_login();$today=date('Y-m-d');$a=one('SELECT * FROM attendance WHERE employee_id=? AND work_date=?',[$u['id'],$today]);if(!$a){$start=DateTime::createFromFormat('Y-m-d H:i:s',$today.' '.setting('work_start','09:00:00'));$now=new DateTime();$late=max(0,(int)(($now->getTimestamp()-$start->getTimestamp())/60));$status=$late>(int)setting('grace_minutes','15')?'Late':'Present';db()->prepare('INSERT INTO attendance(employee_id,work_date,check_in,status,late_minutes) VALUES(?,?,NOW(),?,?)')->execute([$u['id'],$today,$status,$late]);flash('Checked in at '.date('g:i A').'.');log_action('Checked in','attendance');}elseif(!$a['check_out']){db()->prepare('UPDATE attendance SET check_out=NOW(),total_seconds=TIMESTAMPDIFF(SECOND,check_in,NOW()),overtime_minutes=GREATEST(0,TIMESTAMPDIFF(MINUTE,? ,NOW())-TIMESTAMPDIFF(MINUTE,?,?)) WHERE id=?')->execute([$today.' '.setting('work_start','09:00:00'),$today.' '.setting('work_start','09:00:00'),$today.' '.setting('work_end','18:00:00'),$a['id']]);flash('Checked out. Your working time has been recorded.');log_action('Checked out','attendance',$a['id']);}else throw new RuntimeException('Attendance is already completed for today.');header('Location:index.php?page=dashboard');exit; }
  if($action==='employee_save'){admin();$id=(int)($_POST['id']??0);$required=['employee_code','first_name','last_name','email'];foreach($required as $r)if(trim($_POST[$r]??'')==='')throw new RuntimeException('Please complete all required fields.');$photo=upload_file('profile_photo','profiles',['image/jpeg','image/png','image/webp']);$data=[trim($_POST['employee_code']),trim($_POST['first_name']),trim($_POST['last_name']),trim($_POST['phone']),trim($_POST['address']),$_POST['date_of_birth']?:null,$_POST['gender']?:null,(int)$_POST['department_id']?:null,(int)$_POST['job_title_id']?:null,$_POST['joining_date']?:null,$_POST['employment_type'],$_POST['employment_status'],trim($_POST['specialty'])];if($id){$q='UPDATE employees SET employee_code=?,first_name=?,last_name=?,phone=?,address=?,date_of_birth=?,gender=?,department_id=?,job_title_id=?,joining_date=?,employment_type=?,employment_status=?,specialty=?'.($photo?',profile_photo=?':'').' WHERE id=?';if($photo)$data[]=$photo;$data[]=$id;db()->prepare($q)->execute($data);db()->prepare('UPDATE users SET email=? WHERE employee_id=?')->execute([trim($_POST['email']),$id]);}else{db()->prepare('INSERT INTO employees(employee_code,first_name,last_name,phone,address,date_of_birth,gender,department_id,job_title_id,joining_date,employment_type,employment_status,specialty,profile_photo) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([...$data,$photo]);$id=(int)db()->lastInsertId();db()->prepare('INSERT INTO users(employee_id,email,password_hash,role) VALUES(?,?,?,?)')->execute([$id,trim($_POST['email']),password_hash($_POST['new_password']?:'ChangeMe123!',PASSWORD_DEFAULT),$_POST['role']??'employee']);}db()->prepare('DELETE FROM employee_skills WHERE employee_id=?')->execute([$id]);foreach($_POST['software_ids']??[] as $sid)db()->prepare('INSERT INTO employee_skills(employee_id,software_id,skill_level) VALUES(?,?,?)')->execute([$id,(int)$sid,$_POST['skill_level']??'Intermediate']);log_action($id?'Updated employee':'Created employee','employee',$id);flash('Employee saved.');header('Location:index.php?page=employees');exit;}
  if($action==='salary_save'){ $u=admin();$eid=(int)$_POST['employee_id'];$old=one('SELECT base_salary FROM salaries WHERE employee_id=?',[$eid]);$vals=[(float)$_POST['base_salary'],(float)$_POST['allowances'],(float)$_POST['bonuses'],(float)$_POST['deductions'],(float)$_POST['overtime_rate'],$_POST['effective_date'],$eid];db()->prepare('INSERT INTO salaries(base_salary,allowances,bonuses,deductions,overtime_rate,effective_date,employee_id) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE base_salary=VALUES(base_salary),allowances=VALUES(allowances),bonuses=VALUES(bonuses),deductions=VALUES(deductions),overtime_rate=VALUES(overtime_rate),effective_date=VALUES(effective_date)')->execute($vals);db()->prepare('INSERT INTO salary_history(employee_id,old_base,new_base,reason,changed_by) VALUES(?,?,?,?,?)')->execute([$eid,$old['base_salary']??0,$_POST['base_salary'],trim($_POST['reason']),$u['id']]);flash('Salary and history updated.');header('Location:index.php?page=salaries');exit;}
  if($action==='project_save'){ $u=admin();if(!trim($_POST['name']))throw new RuntimeException('Project name is required.');$file=upload_file('attachment','project-files',['application/pdf','image/jpeg','image/png','application/zip','application/x-zip-compressed']);db()->prepare('INSERT INTO projects(name,client,project_type,status,start_date,deadline,description,attachment_path,created_by) VALUES(?,?,?,?,?,?,?,?,?)')->execute([trim($_POST['name']),trim($_POST['client']),trim($_POST['project_type']),$_POST['status'],$_POST['start_date']?:null,$_POST['deadline']?:null,trim($_POST['description']),$file,$u['id']]);$pid=(int)db()->lastInsertId();foreach($_POST['team']??[] as $eid)db()->prepare('INSERT INTO project_assignments(project_id,employee_id,assignment_role) VALUES(?,?,?)')->execute([$pid,(int)$eid,'Team Member']);log_action('Created project','project',$pid);flash('Project created.');header('Location:index.php?page=projects');exit;}
  if($action==='master_save'){admin();$type=$_POST['type'];$name=trim($_POST['name']??'');if(!$name)throw new RuntimeException('A name is required.');$table=$type==='department'?'departments':($type==='title'?'job_titles':'software');$col=$type==='title'?'title':'name';db()->prepare("INSERT INTO $table($col) VALUES(?)")->execute([$name]);flash(ucfirst($type).' added.');header('Location:index.php?page=masters');exit;}
  if($action==='setting_save'){admin();foreach(['studio_name','timezone','currency','work_start','work_end','grace_minutes'] as $k)db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$k,trim($_POST[$k])]);date_default_timezone_set($_POST['timezone']);flash('Studio settings saved.');header('Location:index.php?page=settings');exit;}
  if($action==='notify'){ $u=admin();$target=$_POST['user_id']?:(null);db()->prepare('INSERT INTO notifications(user_id,title,message,type) VALUES(?,?,?,?)')->execute([$target,trim($_POST['title']),trim($_POST['message']),$_POST['type']]);flash('Notification sent.');header('Location:index.php?page=notifications');exit;}
 }catch(Throwable $e){flash($e->getMessage(),'error');header('Location:'.($_SERVER['HTTP_REFERER']??'index.php'));exit;}
