function head($title){global $current;$u=require_login();$f=pull_flash();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=esc($title)?> · <?=esc(setting('studio_name',APP_NAME))?></title><link rel="stylesheet" href="assets/app.css"></head><body><div class="app"><aside class="side"><div class="brand">FRAMEFORGE<small>STUDIO PORTAL</small></div><div class="nav-label">WORKSPACE</div><?=nav('dashboard','Dashboard','◈')?><?=nav('attendance','My Attendance','◷')?><?=nav('profile','My Profile','◉')?><?=nav('salary','My Salary','₨')?><?=nav('projects','Projects','▣')?><?=nav('notifications','Notifications','♢')?><?php if($u['role']==='admin'):?><div class="nav-label">ADMINISTRATION</div><?=nav('employees','Employees','♙')?><?=nav('salaries','Salary & Payroll','₨')?><?=nav('masters','Studio Directory','◌')?><?=nav('reports','Reports','▥')?><?=nav('settings','Settings','⚙')?><?=nav('audit','Audit Log','≡')?><?php endif?></aside><main class="main"><div class="top"><div><h1><?=esc($title)?></h1><div class="sub"><?=esc(date('l, d F Y · g:i A'))?></div></div><div class="user"><span class="user-name"><?=esc($u['first_name'].' '.$u['last_name'])?></span><div class="avatar"><?=esc(strtoupper($u['first_name'][0].$u['last_name'][0]))?></div><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><button class="secondary" name="action" value="logout">Sign out</button></form></div></div><?php if($f):?><div class="alert <?=$f[1]==='error'?'error':''?>"><?=esc($f[0])?></div><?php endif;?><?php }
