ck Out'?></button><?php endif?></form></div><div class="card wide"><div class="section-title"><h2>My active projects</h2><a class="muted" href="index.php?page=projects">View all</a></div><?php $prs=rows('SELECT p.* FROM projects p JOIN project_assignments pa ON pa.project_id=p.id WHERE pa.employee_id=? AND p.status NOT IN("Completed","Archived")',[$u['id']]);foreach($prs as $p):?><p><strong><?=esc($p['name'])?></strong><br><span class="badge <?=strtolower(str_replace(' ','-',$p['status']))?>"><?=esc($p['status'])?></span> <span class="muted">Due <?=esc($p['deadline']?:'TBD')?></span></p><?php endforeach;if(!$prs)echo '<div class="empty">No active project assignments.</div>';?></div><div class="card full"><div class="section-title"><h2>Recent studio activity</h2></div><div class="table-wrap"><table class="table"><tr><th>Employee</th><th>Date</th><th>Check in</th><th>Check out</th><th>Hours</th><th>Status</th></tr><?php foreach(rows('SELECT a.*,e.first_name,e.last_name FROM attendance a JOIN employees e ON e.id=a.employee_id '.($u['role']==='admin'?'':'WHERE a.employee_id=?').' ORDER BY a.work_date DESC LIMIT 8',$u['role']==='admin'?[]:[$u['id']]) as $a):?><tr><td><?=esc($a['first_name'].' '.$a['last_name'])?></td><td><?=esc($a['work_date'])?></td><td><?=esc($a['check_in']?date('g:i A',strtotime($a['check_in'])):'—')?></td><td><?=esc($a['check_out']?date('g:i A',strtotime($a['check_out'])):'—')?></td><td><?=duration($a['total_seconds'])?></td><td><span class="badge <?=strtolower($a['status'])?>"><?=esc($a['status'])?></span></td></tr><?php endforeach?></table></div></div></div><?php foot();exit;}
