['job_title_id']==$j['id']?'selected':''?>><?=esc($j['title'])?></option><?php endforeach?></select></div><div><label>Specialty</label><input name="specialty" value="<?=esc($e['specialty'])?>" placeholder="e.g. Motion Design"></div><div><label>Phone</label><input name="phone" value="<?=esc($e['phone'])?>"></div><div><label>Joining date</label><input type="date" name="joining_date" value="<?=esc($e['joining_date'])?>"></div><div><label>Employment type</label><select name="employment_type"><?php foreach(['Full Time','Part Time','Contract','Freelance','Intern'] as $x):?><option <?=$e['employment_type']===$x?'selected':''?>><?=$x?></option><?php endforeach?></select></div><div><label>Status</label><select name="employment_status"><?php foreach(['Active','Inactive','On Leave','Resigned'] as $x):?><option <?=$e['employment_status']===$x?'selected':''?>><?=$x?></option><?php endforeach?></select></div><div><label>Access role</label><select name="role"><option value="employee" <?=$e['role']==='employee'?'selected':''?>>Employee</option><option value="admin" <?=$e['role']==='admin'?'selected':''?>>Admin</option></select></div><div><label>New password <?=$edit?'(optional)':''?></label><input type="password" name="new_password" placeholder="<?=!$edit?'ChangeMe123!':''?>"></div><div><label>Profile picture</label><input type="file" name="profile_photo" accept="image/png,image/jpeg,image/webp"></div><div class="span2"><label>Software skills</label><div class="actions"><?php foreach(rows('SELECT * FROM software WHERE active=1') as $s):?><label style="font-weight:normal"><input style="width:auto" type="checkbox" name="software_ids[]" value="<?=$s['id']?>"> <?=esc($s['name'])?></label><?php endforeach?></div></div><div><label>Skill level</label><select name="skill_level"><option>Beginner</option><option selected>Intermediate</option><option>Advanced</option><option>Expert</option></select></div><div class="span2"><label>Address</label><textarea name="address"><?=esc($e['address'])?></textarea></div><div class="span2"><button>Save employee</button> <a class="button secondary" href="index.php?page=employees">Cancel</a></div></form></div><?php }else{?><div class="section-title"><h2>Studio crew</h2><a class="button" href="index.php?page=employees&new=1">Add employee</a></div><div class="card table-wrap"><table class="table"><tr><th>Employee</th><th>Role</th><th>Department</th><th>Specialty</th><th>Status</th><th></th></tr><?php foreach($list as $e):?><tr><td><strong><?=esc($e['first_name'].' '.$e['last_name'])?></strong><br><span class="muted"><?=esc($e['employee_code'].' · '.$e['email'])?></span></td><td><?=esc($e['job_title']?:'—')?></td><td><?=esc($e['department_name']?:'—')?></td><td><?=esc($e['specialty'])?></td><td><span class="badge <?=strtolower($e['employment_status'])?>"><?=esc($e['employment_status'])?></span></td><td><a class="button secondary" href="index.php?page=employees&edit=<?=$e['id']?>">Edit</a></td></tr><?php endforeach?></table></div><?php }foot();exit;}
if($page==='salaries'||$page==='salary'){ $u=$page==='salaries'?admin():require_login();$all=$page==='salaries';$data=rows('SELECT s.*,e.id employee_id,e.first_name,e.last_name,e.employee_code,j.title FROM salaries s JOIN employees e ON e.id=s.employee_id LEFT JOIN job_titles j ON j.id=e.job_title_id '.($all?'':'WHERE e.id=?').' ORDER BY e.first_name',$all?[]:[$u['id']]);head($all?'Salary & Payroll':'My Salary');if($all):?><div class="card" style="margin-bottom:16px"><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="salary_save"><div><label>Employee</label><select name="employee_id"><?php foreach(rows('SELECT id,first_name,last_name FROM employees WHERE employment_status="Active"') as $e):?><option value="<?=$e['id']?>"><?=esc($e['first_name'].' '.$e['last_name'])?></option><?php endforeach?></select></div><?php foreach(['base_salary'=>'Base salary','allowances'=>'Allowances','bonuses'=>'Bonus','deductions'=>'Deductions','overtime_rate'=>'Overtime rate'] as $k=>$l):?><div><label><?=$l?></label><input type="number" min="0" step="0.01" name="<?=$k?>" value="0"></div><?php endforeach?><div><label>Effective date</label><input type="date" name="effective_date" value="<?=date('Y-m-d')?>"></div><div><label>Reason</label><input name="reason" placeholder="e.g. Annual review"></div><div style="align-self:end"><button>Record salary change</button></div></form></div><?php endif?><div class="card table-wrap"><table class="table"><tr><th>Employee</th><th>Base</th><th>Allowances</th><th>Bonus</th><th>Deductions</th><th>Net salary</th><th>Effective</th></tr><?php foreach($data as $s):$net=$s['base_salary']+$s['allowances']+$s['bonuses']-$s['deductions'];?><tr><td><strong><?=esc($s['first_name'].' '.$s['last_name'])?></strong><br><span class="muted"><?=esc($s['title'])?></span></td><td><?=fmt_money($s['base_salary'])?></td><td><?=fmt_money($s['allowances'])?></td><td><?=fmt_money($s['bonuses'])?></td><td><?=fmt_money($s['deductions'])?></td><td><strong><?=fmt_money($net)?></strong></td><td><?=esc($s['effective_date'])?></td></tr><?php endforeach?></table></div><?php if(!$all):?><div class="card" style="margin-top:16px"><h2>Salary history</h2><?php foreach(rows('SELECT h.*,e.first_name,e.last_name FROM salary_history h LEFT JOIN employees e ON e.id=h.changed_by WHERE h.employee_id=? ORDER BY h.changed_at DESC',[$u['id']]) as $h):?><p><strong><?=fmt_money($h['old_base'])?> → <?=fmt_money($h['new_base'])?></strong><br><span class="muted"><?=esc($h['reason'])?> · <?=esc($h['changed_at'])?></span></p><?php endforeach?></div><?php endif;foot();exit;}
if($page==='projects'){ $u=require_login();$adminRole=$u['role']==='admin';$projects=rows('SELECT DISTINCT p.* FROM projects p '.($adminRole?'':'JOIN project_assignments pa ON pa.project_id=p.id WHERE pa.employee_id=?').' ORDER BY p.deadline',$adminRole?[]:[$u['id']]);head($adminRole?'Projects & Assignments':'My Projects');if($adminRole):?><div class="card" style="margin-bottom:16px"><form method="post" enctype="multipart/form-data" class="form-grid"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="project_save"><div><label>Project name *</label><input name="name" required></div><div><label>Client</label><input name="client"></div><div><label>Project type</label><input name="project_type" placeholder="Motion Graphics"></div><div><label>Status</label><select name="status"><?php foreach(['Planned','Pre-Production','In Production','Review','Revisions','Completed','Archived'] as $x):?><option><?=$x?></option><?php endforeach?></select></div><div><label>Start</label><input type="date" name="start_date"></div><div><label>Deadline</label><input type="date" name="deadline"></div><div><label>Reference attachment</label><input type="file" name="attachment" accept=".pdf,.zip,image/png,image/jpeg"></div><div><label>Assigned team</label><select multiple name="team[]" size="3"><?php foreach(rows('SELECT id,first_name,last_name FROM employees WHERE employment_status="Active"') as $e):?><option value="<?=$e['id']?>"><?=esc($e['first_name'].' '.$e['last_name'])?></option><?php endforeach?></select></div><div class="span2"><label>Description</label><textarea name="description"></textarea></div><div><button>Create project</button></div></form></div><?php endif?><div class="grid"><?php foreach($projects as $p):?><div class="card"><div class="section-title"><h2><?=esc($p['name'])?></h2><span class="badge <?=strtolower(str_replace(' ','-',$p['status']))?>"><?=esc($p['status'])?></span></div><p class="muted"><?=esc($p['client'].' · '.$p['project_type'])?></p><p><?=esc($p['description'])?></p><p class="muted">Deadline: <?=esc($p['deadline']?:'TBD')?></p><?php $team=rows('SELECT e.first_name,e.last_name,pa.assignment_role FROM project_assignments pa JOIN employees e ON e.id=pa.employee_id WHERE pa.project_id=?',[$p['id']]);foreach($team as $x):?><span class="badge"><?=esc($x['first_name'].' '.$x['last_name'])?></span> <?php endforeach?></div><?php endforeach?></div><?php foot();exit;}
if($page==='profile'){ $u=require_login();$skills=rows('SELECT COALESCE(s.name,es.custom_skill) skill,es.skill_level FROM employee_skills es LEFT JOIN software s ON s.id=es.software_id WHERE es.employee_id=?',[$u['id']]);head('My Profile');?><div class="card profile"><div class="avatar"><?=esc(strtoupper($u['first_name'][0].$u['last_name'][0]))?></div><div><h2><?=esc($u['first_name'].' '.$u['last_name'])?></h2><div class="muted"><?=esc(($u['job_title']?:'Studio crew').' · '.($u['department_name']?:'Unassigned'))?></div><div class="muted"><?=esc($u['employee_code'])?></div></div></div><div class="grid" style="margin-top:16px"><div class="card wide"><h2>Personal information</h2><p><strong>Email</strong><br><?=esc($u['login_email'])?></p><p><strong>Phone</strong><br><?=esc($u['phone']?:'—')?></p><p><strong>Address</strong><br><?=esc($u['address']?:'—')?></p></div><div class="card wide"><h2>Professional profile</h2><p><strong>Specialty</strong><br><?=esc($u['specialty']?:'—')?></p><p><strong>Employment</strong><br><?=esc($u['employment_type'].' · '.$u['employment_status'].' · Joined '.$u['joining_date'])?></p><p><strong>Software skills</strong><br><?php foreach($skills as $s):?><span class="badge"><?=esc($s['skill'].' · '.$s['skill_level'])?></span> <?php endforeach?></p></div></div><?php foot();exit;}
if($page==='notifications'){ $u=require_login();$notes=rows('SELECT * FROM notifications WHERE user_id IS NULL OR user_id=(SELECT id FROM users WHERE employee_id=?) ORDER BY created_at DESC',[$u['id']]);head('Notifications');if($u['role']==='admin'):?><div class="card" style="margin-bottom:16px"><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="notify"><div><label>Recipient</label><select name="user_id"><option value="">All employees</option><?php foreach(rows('SELECT u.id,e.first_name,e.last_name FROM users u JOIN employees e ON e.id=u.employee_id') as $x):?><option value="<?=$x['id']?>"><?=esc($x['first_name'].' '.$x['last_name'])?></option><?php endforeach?></select></div><div><label>Type</label><select name="type"><option value="announcement">Announcement</option><option value="info">Info</option><option value="alert">Alert</option></select></div><div class="span2"><label>Title</label><input name="title" required></div><div class="span2"><label>Message</label><textarea name="message" required></textarea></div><div><button>Send notification</button></div></form></div><?php endif?><div class="grid"><?php foreach($notes as $n):?><div class="card"><span class="badge"><?=esc($n['type'])?></span><h2><?=esc($n['title'])?></h2><p><?=esc($n['message'])?></p><div class="muted"><?=esc($n['created_at'])?></div></div><?php endforeach?></div><?php foot();exit;}
if($page==='masters'){admin();head('Studio Directory');?><div class="grid"><?php foreach(['department'=>'Departments','title'=>'Job Titles','software'=>'Software'] as $type=>$label):?><div class="card"><h2><?=$label?></h2><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="master_save"><input type="hidden" name="type" value="<?=$type?>"><input name="name" required placeholder="Add <?=$label?>"><button>Add</button></form><hr style="border:0;border-top:1px solid #e8ebf2;margin:15px 0"><?php $tbl=$type==='department'?'departments':($type==='title'?'job_titles':'software');$col=$type==='title'?'title':'name';foreach(rows("SELECT $col FROM $tbl WHERE active=1 ORDER BY $col") as $x):?><p><?=esc($x[$col])?></p><?php endforeach?></div><?php endforeach?></div><?php foot();exit;}
if($page==='settings'){admin();head('Studio Settings');?><div class="card"><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="setting_save"><div><label>Studio name</label><input name="studio_name" value="<?=esc(setting('studio_name'))?>"></div><div><label>Timezone</label><input name="timezone" value="<?=esc(setting('timezone','Asia/Karachi'))?>"></div><div><label>Currency</label><input name="currency" value="<?=esc(setting('currency','PKR'))?>"></div><div><label>Grace period (minutes)</label><input type="number" name="grace_minutes" value="<?=esc(setting('grace_minutes','15'))?>"></div><div><label>Working day starts</label><input type="time" name="work_start" value="<?=esc(setting('work_start','09:00:00'))?>"></div><div><label>Working day ends</label><input type="time" name="work_end" value="<?=esc(setting('work_end','18:00:00'))?>"></div><div><button>Save settings</button></div></form></div><?php foot();exit;}
if($page==='reports'){admin();$dept=rows('SELECT d.name,COUNT(e.id) crew,SUM(a.status IN("Present","Late")) attended FROM departments d LEFT JOIN employees e ON e.department_id=d.id LEFT JOIN attendance a ON a.employee_id=e.id AND a.work_date=CURDATE() GROUP BY d.id');head('Attendance Reports');?><div class="card table-wrap"><table class="table"><tr><th>Department</th><th>Active crew</th><th>Present / late today</th></tr><?php foreach($dept as $d):?><tr><td><?=esc($d['name'])?></td><td><?=$d['crew']?></td><td><?=$d['attended']??0?></td></tr><?php endforeach?></table></div><?php foot();exit;}
if($page==='audit'){admin();head('Audit Log');?><div class="card table-wrap"><table class="table"><tr><th>When</th><th>User</th><th>Action</th><th>Entity</th><th>IP</th></tr><?php foreach(rows('SELECT a.*,e.first_name,e.last_name FROM audit_logs a LEFT JOIN employees e ON e.id=a.user_id ORDER BY a.created_at DESC LIMIT 100') as $a):?><tr><td><?=esc($a['created_at'])?></td><td><?=esc(trim($a['first_name'].' '.$a['last_name'])?:'System')?></td><td><?=esc($a['action'])?></td><td><?=esc($a['entity'].' #'.$a['entity_id'])?></td><td><?=esc($a['ip_address'])?></td></tr><?php endforeach?></table></div><?php foot();exit;}
head('Not found');?><div class="card empty">This page does not exist.</div><?php foot();
